    ('097bd79b-a0d9-40d1-832d-c8a0671f7ab3'::uuid, 'period_start', '-3000', '-1500', 'fields-wd1-2026-09-26d-s001-rollback:097bd79b-a0d9-40d1-832d-c8a0671f7ab3:period_start', 'rollback of fields-wd1-2026-09-26d-s001: period_start ''-1500'' restored on Hathial', '[{"source": "https://architexturez.net/doc/10-5334/aa-203", "url": "https://architexturez.net/doc/10-5334/aa-203", "quote": "The archaeological inquiries in Trans-Salt Range Zone of northern Punjab, Pakistan have unveiled the multifaceted data for the cultural development of the Early Harappan-Kot Diji phase of Indus Civilization during third millennium BC. Up until now, the urbanism of Indus Civilization is missing in the area while absolute dating at Sarai Khola, Jhang-Bahater & Hathial, has shown that Kot Diji phase has evolved in the Trans-Salt Range Zone parallel to Harappan phase of Indus Plains.", "outcome": "found"}, {"source": "https://os.pennds.org/archaeobib_filestore/pdf_articles/Antiquity/1982_56_216_Allchin.pdf", "url": "https://os.pennds.org/archaeobib_filestore/pdf_articles/Antiquity/1982_56_216_Allchin.pdf", "quote": "we are presented with a fourth city, but earlier than all three-Hathial-dating back to the middle of the third millennium BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0013)", "decision": "replace", "status": "MISSING", "reasoning": "Allchin (Antiquity 1982) found stratified Kot Dijian deposits at Hathial dating the site back to the middle of the third millennium BC, and Butt (Ancient Asia 2020) reports that absolute dating at Sarai Khola, Jhang-Bahater and Hathial places their Kot Diji phase in the third millennium BC; the c. 1000 BCE date in Wikipedia and DOAM refers to the later red-burnished-ware town, so the first occupation lies in the 3000-1500 BC bucket (value: the third millennium BC as its first year), not the stored 1500-500 BC one.", "value_page": null}]'::jsonb),
